/* Get the list of the active employees whose Position_ID or Job_ID or Supervisory_ID changed  */

CREATE TEMP TABLE VT_STG_EMPLOYEE AS
SELECT *
FROM
    `gcp-project.HRA_STG_WORKDAY_V.STG_EMPLOYEE`
WHERE
    CAST(SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_EMPLOYEE`
    );

CREATE TEMP TABLE VT_STG_ORG_HIERARCHY AS
SELECT
    SUPERVISORY_ORGANIZATION_ID,
    SUPERVISORY_ORGANIZATION_NAME,
    FUNCTIONAL_GROUP_CODE,
    BUSINESS_UNIT_NAME,
    FUNCTIONAL_GROUP_ID,
    FUNCTIONAL_GROUP_NAME
FROM
    `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
WHERE
    CAST(SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
    );

CREATE TEMP TABLE VT_STG_JOB_PROFILE AS
SELECT
    JOB_CODE,
    JOB_TITLE,
    JOB_FAMILY,
    EXECUTIVE_INDICATOR
FROM
    `gcp-project.HRA_STG_WORKDAY_V.STG_JOB_PROFILE`
WHERE
    Inactive = 'False'
    AND CAST(SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            CAST(MAX(SOURCE_FILE_DTTM) AS DATE)
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_JOB_PROFILE`
    );

CREATE TEMP TABLE VT_ADGRP_NTID (
    NTID STRING,
    ADGRP_ID STRING
);

/*AD GROUP - HRA_ALLHR*/
/*All employees in Human Resources (required for TA Dashboard)*/
INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_ALLHR',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    (
        ORG.FUNCTIONAL_GROUP_CODE = 'Human Resources'
        OR ORG.FUNCTIONAL_GROUP_ID = '10001008'
        OR A.position_id IN ('50258926', '50830553')
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

/*AD GROUP - HRA_PITEAM*/
/*All employees in the People Insights team*/
/*supervisory org number
(Debi and Greg including managers and manager's manager (Rache) of the org)
Members of Supervisory Org X Debbi (70002388),
Manager of Supervisory Org X,
Manager's Manager of Supervisory Org X ,
Members of Supervisory Org Y Greg (70002768),
Manager of Supervisory Org Y,
Manager's Manager of Supervisory Org Y
Exclude Nathan Bushey*/
CREATE TEMP TABLE VT_EMP_HRCY_Piteam AS
SELECT
    DISTINCT E.EMPLOYEE_ID,
    E.LEGAL_LAST_NAME,
    E.NTID,
    E.POSITION_ID,
    OH.LEVEL_01_MANAGER_POSITION_ID AS MANAGER_POSITION_ID,
    OH.LEVEL_02_MANAGER_POSITION_ID AS SRMANAGER_POSITION_ID
FROM
    VT_STG_EMPLOYEE AS E
    INNER JOIN `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY` AS OH ON E.SUPERVISORY_ORGANIZATION_ID = OH.SUPERVISORY_ORGANIZATION_ID
    AND E.SUPERVISORY_ORGANIZATION_ID IN ('70002388', '70002768')
WHERE
    CAST(OH.SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
    );

INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_PITEAM',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    ORG.SUPERVISORY_ORGANIZATION_ID IN ('70002388', '70002768')
    AND A.EMPLOYEE_ID IN (
        SELECT
            DISTINCT EMPLOYEE_ID
        FROM
            VT_EMP_HRCY_Piteam
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_PITEAM',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    A.POSITION_ID IN (
        SELECT
            DISTINCT MANAGER_POSITION_ID AS POSITION_ID
        FROM
            VT_EMP_HRCY_Piteam
        UNION
        SELECT
            DISTINCT SRMANAGER_POSITION_ID AS POSITION_ID
        FROM
            VT_EMP_HRCY_Piteam
        WHERE
            SRMANAGER_POSITION_ID <> '50541685'
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

/*AD Group - HRA_HRVP*/
/*HR VPs and Above*/
/*Functional Group = Human Resources and
Executive Indicator in
(Senior Vice President, Vice President, Chief Officer) or
[Job Code = 00750037 <- Job code not reliable]*/
INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_HRVP',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    (
        ORG.FUNCTIONAL_GROUP_CODE = 'Human Resources'
        OR ORG.FUNCTIONAL_GROUP_id = '10001008'
    )
    AND J.EXECUTIVE_INDICATOR IN (
        'Chief Officer',
        'Senior Vice President',
        'Vice President'
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

/*AD Group - HRA_HRESP*/
/*All HR Employees Success Partners at all levels (ESP population)
workday security role:
TMO_HR_PARTNER_MANAGER_RBSG_C
TMO_HR_PARTNER_ADDITIONAL_RBSG_C
HR_PARTNER (not on Employee source file)*/
INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_HRESP',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    (
        A.TMO_HR_PARTNER_MANAGER_RBSG_C = 'YES'
        OR A.TMO_HR_PARTNER_ADDITIONAL_RBSG_C = 'YES'
        OR A.HR_PARTNER = 'Yes'
        OR A.NTID = 'NVitela1'
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

/*AD Group - HRA_TAteam*/
/*All employees in Talent Acquisition*/
/*this is best served by the workday security role: RECRUITER, TMO_RECRUITER_ADDITIONAL_C*/
INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_TATEAM',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    (
        A.TMO_RECRUITER_ADDITIONAL_C = 'YES'
        OR A.RECRUITER = 'Yes'
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

CREATE TEMP TABLE VT_TMP_ORG AS
