/*  get all orgs under Patrice position_id = 50395331 */
CREATE TEMP TABLE VT_HRA_PAI_ORG AS WITH temp_table AS (
    SELECT
        REFERENCE_ID,
        PARENT_REFERENCE_ID,
        0 AS lvl
    FROM
        VT_TMP_ORG AS org
    UNION ALL
    SELECT
        indirect.REFERENCE_ID,
        direct.PARENT_REFERENCE_ID,
        direct.lvl + 1 AS new_lvl
    FROM
        VT_TMP_ORG AS indirect,
        temp_table AS direct
    WHERE
        direct.REFERENCE_ID = indirect.PARENT_REFERENCE_ID
)
SELECT
    REFERENCE_ID AS ORG_ID
FROM
    temp_table
WHERE
    PARENT_REFERENCE_ID IN (
        SELECT
            DISTINCT SUPERVISORY_ORGANIZATION_ID
