/* getting all position id's including 50395331 excluding (50516252, 50490998)*/
CREATE TEMP TABLE VT_HRAPAI_POSITIONS AS
SELECT
    DISTINCT POSITION_ID
FROM
    VT_STG_EMPLOYEE
WHERE
    (
        SUPERVISORY_ORGANIZATION_ID IN (
            SELECT
                org_id
            FROM
                VT_HRA_PAI_ORG
            WHERE
                ORG_ID NOT IN (
                    SELECT
                        ORG_ID
                    FROM
                        VT_HRA_PAI_ORG_AVOID
                )
        )
        AND POSITION_ID NOT IN ('50516252', '50490998')
    )
    OR POSITION_ID = '50395331';

INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_HRPAI',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    A.POSITION_ID IN (
        SELECT
            POSITION_ID
        FROM
            VT_HRAPAI_POSITIONS
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

