INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_COMMISSIONS',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
