        )
        OR A.POSITION_ID IN (
            SELECT
                POSITION_ID
            FROM
                VT_L1_MANAGER_PSTN_ID_COMMISSIONS
        )
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

/*AD Group - HRA_DIRECTOR*/
/*Employees that are
  directors, sr. directors, VP,
  Sr. VP, Exec. VP, CEO*/
