/*AD Group - HRA_EXECASST*/
/*Executive Assistants
Employees with the business title of Assistant,
Executive or Assistant,
Executive to EVP or Sr. Assistant, Executive:
Job Family Name = Executive Support and
Job profile = Active
List of Job profiles:
Assistant, Executive; Assistant, Executive to COO;
Assistant, Executive to EVP; Sr Assistant, Executive;
Sr Manager, Office of the CEO*/
INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_EXECASST',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    (
        TRIM(J.JOB_FAMILY) IN ('Executive Support', 'General Support')
        OR TRIM(LEADING '0' FROM J.JOB_CODE) IN ('750048', '771726', '771610')
        OR A.NTID = 'JGRIFFI11'
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

/*AD GROUP - HRA_COMP*/
CREATE TEMP TABLE VT_CTE1 AS
SELECT
    DISTINCT EMPLOYEE_ID,
    MANAGER_ID
FROM
    `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
WHERE
    CAST(SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
    )
    AND TERMINATED = 'N'
    AND EMFUNCTION = '10001008'
    AND JOB_CODE IN (
        SELECT
            JOB_CODE
        FROM
            VT_STG_JOB_PROFILE
        WHERE
            job_family = 'Compensation'
    );

CREATE TEMP TABLE VT_CTE2 AS
SELECT
    EM.EMPLOYEE_ID
FROM
    VT_CTE1
    INNER JOIN `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL` AS EM ON EM.MANAGER_ID = VT_CTE1.EMPLOYEE_ID
WHERE
    CAST(SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
    )
    AND TERMINATED = 'N';

INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_COMP',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    A.EMPLOYEE_ID IN (
        SELECT
            EMPLOYEE_ID
        FROM
            VT_CTE1
        UNION
        SELECT
            EMPLOYEE_ID
        FROM
            VT_CTE2
        UNION
        SELECT
            MANAGER_ID
