----------HRA_ResourcePlanning --------------------
/*
Active employees with customorg_functionalgroup_id='10001005' ---Customer Experience
customorg_area = '20001062' ---Planning and Strategy
job_title shouldn't be adminstrative
Manager position title should contain %MANAGER, BUSINESS ANALYSIS%  or %RESOURCE PLANNING%
*/
CREATE TEMP TABLE VT_ResourcePlanning AS
SELECT
    EMPLOYEE_ID
FROM
    `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
WHERE
    EMFUNCTION = '10001005'
    AND AREA = '20001062'
    AND ACTIVE_STATUS = 'Y'
    AND JOB_TITLE NOT LIKE '%ADMINISTRATIVE%'
    AND CAST(SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
    )
    AND MANAGER_ID IN (
        SELECT
            EMPLOYEE_ID
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
        WHERE
            (
                POSITION_TITLE LIKE '%MANAGER, BUSINESS ANALYSIS%'
                OR POSITION_TITLE LIKE '%RESOURCE PLANNING%'
            )
            AND ACTIVE_STATUS = 'Y'
            AND CAST(SOURCE_FILE_DTTM AS DATE) = (
                SELECT
                    MAX(CAST(SOURCE_FILE_DTTM AS DATE))
                FROM
                    `gcp-project.HRA_STG_WORKDAY_V.STG_EM_PERSONAL`
            )
    );

INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_ResourcePlanning',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    A.EMPLOYEE_ID IN (
        SELECT
            EMPLOYEE_ID
        FROM
            VT_ResourcePlanning
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

----------AD GROUP - HRA_HRSRPLUS--------------------
/*
employees who is rolling up to Heddy Gagne, POSITION_ID = 50829146
OR
Functional group ‘Human Resources’ and executive indicator should be director or above
(Plus)
Whoever is managing organization 'Human Resources', adding that person to ADGroup 'HRA_HRSRPLUS'
*/
CREATE TEMP TABLE VT_HRA_HRSRPLUS AS WITH temp_table AS (
    SELECT
        REFERENCE_ID,
        PARENT_REFERENCE_ID,
        0 AS lvl
    FROM
        VT_TMP_ORG AS org
    UNION ALL
    SELECT
        indirect.REFERENCE_ID,
        direct.PARENT_REFERENCE_ID,
        direct.lvl + 1 AS new_lvl
    FROM
        VT_TMP_ORG AS indirect,
        temp_table AS direct
    WHERE
        direct.REFERENCE_ID = indirect.PARENT_REFERENCE_ID
)
SELECT
    REFERENCE_ID AS ORG_ID
FROM
    temp_table
WHERE
    PARENT_REFERENCE_ID IN (
        SELECT
            DISTINCT SUPERVISORY_ORGANIZATION_ID
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
        WHERE
            LEVEL_01_MANAGER_POSITION_ID = '50829146'
            AND DATE(SOURCE_FILE_DTTM) = (
                SELECT
                    MAX(DATE(SOURCE_FILE_DTTM))
                FROM
                    `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
            )
    )
UNION
SELECT
    PARENT_REFERENCE_ID AS ORG_ID
FROM
    temp_table
WHERE
    PARENT_REFERENCE_ID IN (
        SELECT
            DISTINCT SUPERVISORY_ORGANIZATION_ID
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
        WHERE
            LEVEL_01_MANAGER_POSITION_ID = '50829146'
            AND DATE(SOURCE_FILE_DTTM) = (
                SELECT
                    MAX(DATE(SOURCE_FILE_DTTM))
                FROM
                    `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
            )
    )
UNION
SELECT
    REFERENCE_ID AS ORG_ID
FROM
    temp_table
WHERE
    REFERENCE_ID IN (
        SELECT
            DISTINCT SUPERVISORY_ORGANIZATION_ID
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
        WHERE
            LEVEL_01_MANAGER_POSITION_ID = '50829146'
            AND DATE(SOURCE_FILE_DTTM) = (
                SELECT
                    MAX(DATE(SOURCE_FILE_DTTM))
                FROM
                    `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
            )
    );

--VT_EMP_HRA_HRSRPLUS
CREATE TEMP TABLE VT_EMP_HRA_HRSRPLUS AS
SELECT
    DISTINCT A.EMPLOYEE_ID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY` AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    CAST(ORG.SOURCE_FILE_DTTM AS DATE) = (
        SELECT
            MAX(CAST(SOURCE_FILE_DTTM AS DATE))
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
    )
    AND (
        ORG.SUPERVISORY_ORGANIZATION_ID IN (
            SELECT
                ORG_ID
            FROM
                VT_HRA_HRSRPLUS
        ) ---- employees who is rolling up to Heddy Gagne
        OR (
            (
                ORG.FUNCTIONAL_GROUP_CODE = 'Human Resources'
                OR ORG.FUNCTIONAL_GROUP_id = '10001008'
            )
            AND J.EXECUTIVE_INDICATOR IN (
                'Director',
                'Chief Officer',
                'Vice President',
                'Senior Director',
                'Senior Vice President',
                'Senior Director IC',
                'Director IC'
            )
        ) -- functional group 'Human Resources' and executive indicator should be director or above
    )
UNION
----- Whoever is managing organization 'Human Resources', adding that person to ADGroup 'HRA_HRSRPLUS'
SELECT
    DISTINCT A.EMPLOYEE_ID
FROM
    VT_STG_EMPLOYEE AS A
WHERE
    A.POSITION_ID IN (
        SELECT
            LEVEL_01_MANAGER_POSITION_ID
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
        WHERE
            SUPERVISORY_ORGANIZATION_ID = '70010541'
            AND CAST(SOURCE_FILE_DTTM AS DATE) = (
                SELECT
                    MAX(CAST(SOURCE_FILE_DTTM AS DATE))
                FROM
                    `gcp-project.HRA_STG_WORKDAY_V.STG_ORG_HIERARCHY`
            )
    );

INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT 'HRA_HRSRPLUS',
    A.NTID
FROM
    VT_STG_EMPLOYEE AS A
    INNER JOIN VT_STG_ORG_HIERARCHY AS ORG ON A.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    INNER JOIN VT_STG_JOB_PROFILE AS J ON A.JOB_ID = J.JOB_CODE
WHERE
    A.EMPLOYEE_ID IN (
        SELECT
            EMPLOYEE_ID
        FROM
            VT_EMP_HRA_HRSRPLUS
    )
    AND CASE
        WHEN A.EMPLOYMENT_STATUS = 'Terminated' THEN 'R'
        WHEN A.EMPLOYMENT_STATUS = 'Active' THEN 'A'
        ELSE 'R'
    END = 'A';

