INSERT INTO
    VT_ADGRP_NTID (ADGRP_ID, NTID)
SELECT
    DISTINCT ADGRP_ID,
    NTID
FROM
    (
        SELECT
            *
        FROM
            `gcp-project.HRA_CORE_V.HRA_PROC_ADGRP_MANUALUSERS`
    ) AS A
WHERE
    ACTION_IND = 'A'
    AND Row_Number() Over(
        PARTITION BY
            NTID,
            ADGRP_ID
        ORDER BY
            LOAD_DTTM DESC
    ) = 1;

/*CREATE MULTISET VOLATILE TABLE VT_STG_EMPLOYEE_OLD AS
 (SELECT * FROM HRA_STG_WORKDAY_V.STG_EMPLOYEE
QUALIFY Row_Number() Over(PARTITION BY EMPLOYEE_ID ORDER BY SOURCE_FILE_DTTM ASC) = 1
) WITH DATA PRIMARY INDEX(EMPLOYEE_ID)
ON COMMIT PRESERVE ROWS;

CREATE MULTISET VOLATILE TABLE VT_STG_EMPLOYEE_NEW AS
 (SELECT * FROM HRA_STG_WORKDAY_V.STG_EMPLOYEE
QUALIFY Row_Number() Over(PARTITION BY EMPLOYEE_ID ORDER BY SOURCE_FILE_DTTM DESC) = 1
) WITH DATA PRIMARY INDEX(EMPLOYEE_ID)
ON COMMIT PRESERVE ROWS;*/
DELETE FROM `gcp-project.HRA_CORE_T.ASSOCIATE_ADGROUP_ANOMALY_SNAPSHOT` WHERE TRUE;

INSERT INTO
    `gcp-project.HRA_CORE_T.ASSOCIATE_ADGROUP_ANOMALY_SNAPSHOT` (
        ASSOC_USER_NAME,
        ASSOC_ADGROUP_ID,
        EMPLOYEE_ID,
        LEGAL_FIRST_NAME,
        LEGAL_MIDDLE_NAME,
        LEGAL_LAST_NAME,
        EMPLOYMENT_STATUS,
        HIRE_DATE,
        TERM_DATE,
        FUNCTIONAL_GROUP_NAME,
        JOB_TITLE,
        SNAPSHOT_DATE
    )
SELECT
    A.ASSOC_USER_NAME,
    A.ASSOC_ADGROUP_ID,
    /*C.NTID AS OLDNTID,
    D.NTID AS NEWNTID,
    CASE WHEN A.ASSOC_USER_NAME <> C.NTID THEN 1
    WHEN A.ASSOC_USER_NAME <> D.NTID THEN 1
    ELSE 0 END,*/
    B.EMPLOYEE_ID,
    B.LEGAL_FIRST_NAME,
    B.LEGAL_MIDDLE_NAME,
    B.LEGAL_LAST_NAME,
    B.EMPLOYMENT_STATUS,
    B.HIRE_DATE,
    CASE
        WHEN B.HIRE_DATE < B.TERMINATION_DATE THEN B.TERMINATION_DATE
    END AS TERM_DATE,
    ORG.FUNCTIONAL_GROUP_NAME,
    --ORG.FUNCTIONAL_GROUP_ID
    J.JOB_TITLE,
    CURRENT_DATE AS SNAPSHOT_DATE
FROM
    (
        SELECT
            DISTINCT TRIM(ASSOC_USER_NAME) AS ASSOC_USER_NAME,
            TRIM(ASSOC_ADGROUP_ID) AS ASSOC_ADGROUP_ID
        FROM
            `gcp-project.HRA_CORE_V.ASSOCIATE_ADGROUP_SNAPSHOT`
        EXCEPT DISTINCT
        SELECT
            DISTINCT TRIM(NTID) AS ASSOC_USER_NAME,
            TRIM(ADGRP_ID) AS ASSOC_ADGROUP_ID
        FROM
            VT_ADGRP_NTID
    ) AS A
    LEFT OUTER JOIN (
        SELECT
            *
        FROM
            `gcp-project.HRA_STG_WORKDAY_V.STG_EMPLOYEE`
    ) AS B ON A.ASSOC_USER_NAME = B.NTID
    LEFT OUTER JOIN VT_STG_ORG_HIERARCHY AS ORG ON B.SUPERVISORY_ORGANIZATION_ID = ORG.SUPERVISORY_ORGANIZATION_ID
    LEFT OUTER JOIN VT_STG_JOB_PROFILE AS J ON B.JOB_ID = J.JOB_CODE
    /*LEFT OUTER JOIN VT_STG_EMPLOYEE_OLD  C
    ON C.EMPLOYEE_ID = B.EMPLOYEE_ID

    LEFT OUTER JOIN  VT_STG_EMPLOYEE_NEW  D
    ON D.EMPLOYEE_ID = B.EMPLOYEE_ID*/
WHERE
    Row_Number() Over(
        PARTITION BY
            NTID
        ORDER BY
            SOURCE_FILE_DTTM DESC
    ) = 1;

